analytics-sessionizer.fixed_code:
"""Group raw click events into user sessions for the analytics dashboard.

A session is a run of events from one user where no two consecutive events are more than
SESSION_GAP seconds apart. Events arrive from several ingest workers, so they are NOT guaranteed
to be in timestamp order.
"""

from collections import defaultdict
from dataclasses import dataclass, field

SESSION_GAP = 30 * 60  # seconds of inactivity that end a session


@dataclass
class Event:
    user_id: str
    ts: int  # unix seconds
    page: str


@dataclass
class Session:
    user_id: str
    start: int
    end: int
    pages: list[str] = field(default_factory=list)

    @property
    def duration(self) -> int:
        return self.end - self.start


def sessionize(events):
    """Return {user_id: [Session, ...]} with each user's sessions in chronological order."""
    by_user = defaultdict(list)
    for ev in events:
        by_user[ev.user_id].append(ev)

    result = {}
    for user_id, user_events in by_user.items():
        sessions = []
        current = None
        for ev in sorted(user_events, key=lambda e: e.ts):
            if current is None or ev.ts - current.end > SESSION_GAP:
                current = Session(user_id, ev.ts, ev.ts, [ev.page])
                sessions.append(current)
            else:
                current.end = ev.ts
                current.pages.append(ev.page)
        result[user_id] = sessions
    return result


def average_session_seconds(events):
    sessions = [s for user in sessionize(events).values() for s in user]
    if not sessions:
        return 0.0
    return sum(s.duration for s in sessions) / len(sessions)

deploy-order.fixed_code:
"""Work out the order to start services in for a deploy.

`graph` maps each service to the services it depends on. A service may only start after every
service it depends on (directly or transitively) has started. A dependency cycle is a
configuration error and must raise CycleError rather than produce an order.
"""


class CycleError(Exception):
    pass


class Resolver:
    def __init__(self, graph):
        self.graph = graph
        self._cache = {}

    def start_order(self, service):
        """Return `service` and everything it depends on, dependencies first, `service` last."""
        if service in self._cache:
            return list(self._cache[service])

        order = []
        visited = set()
        in_progress = set()

        def visit(node):
            if node in visited:
                return
            if node in in_progress:
                raise CycleError(f"dependency cycle through {node!r}")
            in_progress.add(node)
            for dep in self.graph.get(node, []):
                visit(dep)
            in_progress.discard(node)
            visited.add(node)
            order.append(node)

        visit(service)
        self._cache[service] = order
        return list(order)


def plan_deploy(resolver, targets, already_running=()):
    """Return the services to start, in a valid order, to bring every target up.

    Services in `already_running` are skipped. Each service appears at most once.
    """
    steps = []
    for target in targets:
        order = resolver.start_order(target)
        for name in already_running:
            if name in order:
                order.remove(name)
        steps.extend(order)
    return list(dict.fromkeys(steps))

